        List<Trash> allEnergy = repository.findAll();

        System.out.println("🔍 Total Energy Documents found in DB: " + allEnergy.size());

        // 2. Filter l'Dates f'Java (Hna l'control 100% dyalek)
        Double consumedEnergy = allEnergy.stream()
                .filter(e -> {
                    // Verifier nulls
                    if (e.getCreatedAt() == null || e.getWight() == null) return false;

                    // Verifier la date (Java Logic)
                    // isAfter/Equal Start AND isBefore/Equal End
                    boolean isAfterStart = !e.getCreatedAt().isBefore(start);
                    boolean isBeforeEnd = !e.getCreatedAt().isAfter(end);

                    return isAfterStart && isBeforeEnd;
                })
                .mapToDouble(Trash::getWight)
                .sum();

        System.out.println("✅ Filtered Energy (" + start + " -> " + end + "): " + consumedEnergy);

        return consumedEnergy;
    }

